const vr=$json.valueRanges||[];
const g=v=>(v&&(v.valueRange||v).values)||[];
let inv=null,onb=null,bnc=null;
for(const v of vr){const rs=g(v);const h=(rs[0]||[]).map(x=>String(x||'').toLowerCase());
 if(h.includes('contact_person'))inv=rs; else if(h.includes('bounced_address'))bnc=rs; else if(h.includes('status')&&h.includes('firm'))onb=rs;}
if(!inv||!onb)return[{json:{abort:true,reason:'ranges not identified'}}];
bnc=bnc||[['detected_at']];
const A=n=>{let s='';while(n>=0){s=String.fromCharCode(65+(n%26))+s;n=Math.floor(n/26)-1;}return s;};
const nowIso=new Date().toISOString().slice(0,19).replace('T',' ');

// ---- collect bounce messages from all five mailboxes
const boxes={MB5:'Shradhaa',MB4:'Akansha',MB3:'investors@',MB2:'dealflow@',MB6:'admin@'};
const HARD=/550|5\.1\.1|5\.1\.10|address not found|couldn.t be found|does not exist|no such user|user unknown|recipient not found/i;
const SOFT=/blocked|4\.\d\.\d|quota|temporarily|try again|deferred|rejected|policy/i;
const found=[];
for(const [node,label] of Object.entries(boxes)){
 let items=[]; try{ items=$(node).all(); }catch(e){ continue; }
 for(const it of items){ const j=it.json||{};
  const from=String(j.from&&j.from.text?j.from.text:(j.from||''));
  const subj=String(j.subject||'');
  const body=String(j.text||'');
  if(!/mailer-daemon|postmaster|delivery status|undeliverable|address not found/i.test(from+' '+subj)) continue;
  const all=(body.match(/[\w.+-]+@[\w-]+\.[\w.-]+/g)||[]).map(x=>x.toLowerCase());
  const cand=all.filter(a=>!/sidanaventures\.com|googlemail|google\.com|gmail\.com$/.test(a)
    && !/^(mailer-daemon|postmaster|no-?reply|noreply)@/.test(a));
  if(!cand.length) continue;
  const addr=cand[0];
  const hard=HARD.test(body); const soft=!hard&&SOFT.test(body);
  const m=body.match(/(?:The response (?:was|from the remote server was)|Reason|status code)\s*:?\s*([^\n]{0,140})/i);
  found.push({addr, dom:addr.split('@')[1]||'', hard:hard?'HARD':(soft?'SOFT':'UNKNOWN'),
    reason:(m?m[1]:subj).replace(/\s+/g,' ').trim().slice(0,140),
    date:String(j.date||'').slice(0,25), mailbox:label});
 }
}
// dedupe on address + day
const seen=new Set(); const uniq=[];
for(const b of found){ const k=b.addr+'|'+String(b.date).slice(0,16); if(seen.has(k))continue; seen.add(k); uniq.push(b); }

// already logged?
const bh=(bnc[0]||[]).map(x=>String(x||'').trim().toLowerCase());
const bAddr=bh.indexOf('bounced_address'), bDate=bh.indexOf('bounce_date');
const logged=new Set();
for(let i=1;i<bnc.length;i++){ const r=bnc[i]||[];
 if(String(r[bAddr]||'').trim()) logged.add(String(r[bAddr]).trim().toLowerCase()+'|'+String(r[bDate]||'').slice(0,16)); }
let lastB=0; for(let i=1;i<bnc.length;i++){ if(String((bnc[i]||[])[bAddr]||'').trim()) lastB=i; }
let nextB=lastB+2;

// ---- match against the book and the campaign
const ih=inv[0].map(x=>String(x||'').trim().toLowerCase());
const iN=ih.indexOf('investor'),iE=ih.indexOf('email'),iC=ih.indexOf('cc');
const invBy={};
for(let i=1;i<inv.length;i++){ for(const c of [iE,iC]){
 for(const part of String((inv[i]||[])[c]||'').split(/[,;\s]+/)){ const e=part.trim().toLowerCase();
  if(e.includes('@')&&!invBy[e]) invBy[e]={row:i+1,name:String(inv[i][iN]||'')}; } } }
const oh=onb[0].map(x=>String(x||'').trim().toLowerCase());
const oE=oh.indexOf('email'),oCS=oh.indexOf('contact_status'),oS=oh.indexOf('status'),oRN=oh.indexOf('review_note'),oF=oh.indexOf('firm');
const onbBy={};
for(let i=1;i<onb.length;i++){ const e=String((onb[i]||[])[oE]||'').trim().toLowerCase();
 if(e&&!onbBy[e]) onbBy[e]={row:i+1,firm:String(onb[i][oF]||''),cs:String(onb[i][oCS]||''),st:String(onb[i][oS]||'')}; }

const newRows=[]; const onbUpdates=[]; const report=[];
for(const b of uniq){
 if(logged.has(b.addr+'|'+String(b.date).slice(0,16))) continue;
 const iv=invBy[b.addr]||null; const ob=onbBy[b.addr]||null;
 let action='logged only';
 if(b.hard==='HARD' && ob){
  onbUpdates.push({range:'ONBOARDING!'+A(oCS)+ob.row,values:[['BOUNCED']]});
  if(/^(QUEUED)$/i.test(ob.st)) onbUpdates.push({range:'ONBOARDING!'+A(oS)+ob.row,values:[['HOLD']]});
  if(oRN>=0) onbUpdates.push({range:'ONBOARDING!'+A(oRN)+ob.row,values:[['HARD BOUNCE '+String(b.date).slice(0,16)+' - '+b.reason]]});
  action='ONBOARDING row '+ob.row+' set BOUNCED'+(/^(QUEUED)$/i.test(ob.st)?' + HOLD':'');
 }
 newRows.push([nowIso,b.addr,b.dom,b.hard,b.reason,b.date,b.mailbox,
   iv?'YES':'no', iv?iv.row:'', iv?iv.name:'', ob?'YES':'no', ob?ob.row:'', action,
   iv?'INVESTORS row needs a replacement contact - not auto-changed':'']);
 report.push({addr:b.addr,type:b.hard,mailbox:b.mailbox,date:b.date,inBook:iv?iv.name:null,onbRow:ob?ob.row:null,action});
}
const data=[...onbUpdates];
if(newRows.length) data.push({range:'BOUNCES!A'+nextB+':N'+(nextB+newRows.length-1),values:newRows});
return [{json:{abort:data.length===0, scanned:uniq.length, newBounces:newRows.length,
  hardBouncesInBook:report.filter(r=>r.type==='HARD'&&r.inBook).length,
  report, body:{valueInputOption:'RAW',data}}}];

